import{_ as t}from"./chunks/intro-state-return.BV_ci4kz.js";import{_ as a,o as s,c as r,a6 as o}from"./chunks/framework.CJJTSwtO.js";const i="/usa/sales-tax/pr-preview/pr-30/images/why-taxjar-light.webp",n="/usa/sales-tax/pr-preview/pr-30/images/intro-jurisdictions-map.webp",l="/usa/sales-tax/pr-preview/pr-30/images/intro-nexus-thresholds.webp",h="/usa/sales-tax/pr-preview/pr-30/images/intro-product-categories.webp",c="/usa/sales-tax/pr-preview/pr-30/images/intro-exempt-customers.webp",T=JSON.parse('{"title":"Introduction to US Sales Tax","description":"What TaxJar does for US sales tax: the rates of each jurisdiction, state nexus, product and customer exemptions, and return filing with AutoFile.","frontmatter":{"title":"Introduction to US Sales Tax","description":"What TaxJar does for US sales tax: the rates of each jurisdiction, state nexus, product and customer exemptions, and return filing with AutoFile.","type":"explanation"},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md"}'),u={name:"getting-started/introduction.md"};function p(m,e,x,d,f,g){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>TaxJar helps you manage your whole sales tax lifecycle from tax computation to return filing, with TaxJar Integration in place you will be able to do all of this inside ERPNext.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p><img src="'+i+'" alt="Four icons: jurisdiction-based tax rates, state nexus management, tax exemption management and sales tax return filing"></p><h3 id="sales-tax-rates" tabindex="-1">Sales Tax Rates <a class="header-anchor" href="#sales-tax-rates" aria-label="Permalink to &quot;Sales Tax Rates&quot;">​</a></h3><p>The United States has about 12,000 jurisdictions, each with its own combination of tax rates. TaxJar keeps up with the latest rates across all of them, so you always charge the correct tax.</p><p><img src="'+n+'" alt="A map of the United States with the number of sales tax jurisdictions in each state, from 0 in Oregon to 1,659 in Texas. Source: Vertex, Inc."></p><h3 id="state-nexus-management" tabindex="-1">State Nexus Management <a class="header-anchor" href="#state-nexus-management" aria-label="Permalink to &quot;State Nexus Management&quot;">​</a></h3><p>Each of the 50 states has its own threshold for when you must start to collect sales tax: a sales amount, a number of transactions, or both. TaxJar tracks your sales against these thresholds in every state.</p><p><img src="'+l+'" alt="TaxJar cards for states where you may have economic nexus, with the sales and the number of transactions against the limit of each state"></p><h3 id="tax-exemption-management" tabindex="-1">Tax Exemption Management <a class="header-anchor" href="#tax-exemption-management" aria-label="Permalink to &quot;Tax Exemption Management&quot;">​</a></h3><p>Some products are exempt in some states, for example clothing is taxed in California but not in New Jersey. Some customers, such as resellers, are exempt too. TaxJar keeps these rules and applies them on each sale.</p><p><img src="'+h+'" alt="The TaxJar Product Category Lookup with the categories, their codes and descriptions, for example Clothing 20010"></p><p><img src="'+c+'" alt="The TaxJar Tax Exempt Customers list with the exemption type, the exempt region and the certificate of each customer"></p><h3 id="sales-tax-return-filing" tabindex="-1">Sales Tax Return Filing <a class="header-anchor" href="#sales-tax-return-filing" aria-label="Permalink to &quot;Sales Tax Return Filing&quot;">​</a></h3><p>Each state needs its own sales tax return, which is a lot of work across many states. With TaxJar, you know your tax liability in each state, and with TaxJar AutoFile, you file the returns for all your states with one click.</p><p><img src="'+t+'" alt="The TaxJar sales tax report for New York for one quarter, with the tax collected and the button Enroll in AutoFile"></p><p>Next, read the <a href="/usa/sales-tax/pr-preview/pr-30/getting-started/walkthrough">Walkthrough</a> to see what you can do in ERPNext, and watch a video of all features.</p>',18)])])}const b=a(u,[["render",p]]);export{T as __pageData,b as default};
